#!/bin/sh
# Name: Lexi: Set up from phone
# Author: Lexi
# DontUseFBInk
# Icon: data:image/png;base64,
#
# Lexi scriptlet: tap it in the Kindle library. Shows a QR code: scan it to paste your API key and pick a model on your phone.
# Needs the Lexi KOReader plugin (koreader/plugins/lexi.koplugin): see its README.
#
# The library may run scriptlets as the framework user; Lexi needs root for its firewall rule and
# /var/run files, so it goes through the jailbreak's su. Results show in Lexi's own window.
LEXI=/mnt/us/koreader/plugins/lexi.koplugin/native/lexi.sh
if [ ! -f "$LEXI" ]; then
    eips 2 30 "Lexi: install the Lexi KOReader plugin first" > /dev/null 2>&1
elif [ "$(id -u)" = 0 ]; then
    LEXI_UI=dialog sh "$LEXI" setup > /dev/null 2>&1
else
    /var/local/mkk/su -c "LEXI_UI=dialog sh $LEXI setup" > /dev/null 2>&1
fi
